import{_ as e,o as a,c as i,a0 as n}from"./chunks/framework.C3yZ6M33.js";const c=JSON.parse('{"title":"Run a CI runner node","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/run-a-ci-node.md","filePath":"how-to/run-a-ci-node.md"}'),t={name:"how-to/run-a-ci-node.md"};function h(o,s,l,p,r,d){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="run-a-ci-runner-node" tabindex="-1">Run a CI runner node <a class="header-anchor" href="#run-a-ci-runner-node" aria-label="Permalink to &quot;Run a CI runner node&quot;">​</a></h1><p>GitHub Actions runners (or any ephemeral host) can join the entity plane as first-class nodes: boot <code>peregrin serve --ephemeral</code>, let the hub schedule work onto it, and on shutdown the node flushes snapshots of everything still live so nothing dies with the runner.</p><h2 id="boot" tabindex="-1">Boot <a class="header-anchor" href="#boot" aria-label="Permalink to &quot;Boot&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ephemeral</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or equivalently:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PEREGRIN_EPHEMERAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the standalone daemon reads the env var too:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PEREGRIN_EPHEMERAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> peregrin-node</span></span></code></pre></div><p>Minimum env for a runner:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # reachable from the hub</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18787</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shared-secret</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # REQUIRED off-loopback</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_EPHEMERAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$RUNNER_TEMP/peregrin   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># per-job home</span></span></code></pre></div><h2 id="auth-—-no-pairing-needed" tabindex="-1">Auth — no pairing needed <a class="header-anchor" href="#auth-—-no-pairing-needed" aria-label="Permalink to &quot;Auth — no pairing needed&quot;">​</a></h2><p>Node→hub trust is <strong>configuration, not pairing</strong>. The hub&#39;s operator lists the runner in <code>PEREGRIN_NODES</code> (or <code>HYPHA_NODES</code>) like any other node:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># on the hub</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PEREGRIN_NODES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;durable=http://127.0.0.1:18787@tok1;ci=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$RUNNER_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@tok2&quot;</span></span></code></pre></div><p>The runner itself needs only <code>PEREGRIN_TOKEN</code> — the bearer clients (hub, CLI) present. <code>peregrin pair</code> is a <em>client↔node</em> web-UI flow and plays no part in a node joining a hub; ephemeral mode does not weaken or bypass any auth — a non-loopback bind without <code>PEREGRIN_TOKEN</code> still refuses to start.</p><h2 id="what-survives-shutdown" tabindex="-1">What survives shutdown <a class="header-anchor" href="#what-survives-shutdown" aria-label="Permalink to &quot;What survives shutdown&quot;">​</a></h2><p>On SIGINT <strong>or SIGTERM</strong> (what orchestrators actually send) the node:</p><ol><li>stops accepting connections (graceful drain),</li><li>exports a snapshot of every entity that is <code>live</code> or <code>locked</code> on every registered kind plane (<code>sepia-session</code>, <code>campaign</code>, …),</li><li>closes the session plane as usual.</li></ol><p>Snapshots land in two places, both best-effort:</p><ul><li><p><strong>Local</strong>: <code>$PEREGRIN_SNAPSHOT_DIR/&lt;kind&gt;/&lt;id&gt;.snapshot.json</code> (default <code>$PEREGRIN_HOME/snapshots</code>) plus an <code>index.json</code> manifest. On CI, point <code>PEREGRIN_HOME</code> at a workspace volume or upload the snapshots dir as a job artifact.</p></li><li><p><strong>Handoff</strong>: set <code>PEREGRIN_SNAPSHOT_TARGET</code> to a surviving peer node (or the hub) and each snapshot is POSTed to <code>POST /api/entities/snapshot</code> during shutdown, so the entity resumes where it can keep running:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_SNAPSHOT_TARGET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://durable-node:18787</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_SNAPSHOT_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">that node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;s bearer&gt;   # optional;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">                                                    # falls back to PEREGRIN_TOKEN</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"># when the target is a HUB, pick the import node explicitly:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">export PEREGRIN_SNAPSHOT_NODE=durable</span></span></code></pre></div><p>The hub stores no snapshots itself — its import route forwards to a registered node, which is why the target can be &quot;a node or a hub&quot;.</p></li></ul><p>Entity ops queued hub-side in the durable outbox already survive a node dying — the flush covers entity <em>state</em> (session IR, campaign run checkpoints), which only the node itself can export.</p><h2 id="locks" tabindex="-1">Locks <a class="header-anchor" href="#locks" aria-label="Permalink to &quot;Locks&quot;">​</a></h2><p>No explicit lock cleanup is needed: the hub&#39;s lock book is in-memory and arbitrates stale holds (<code>hypha-control</code>, ~30s stale threshold) — a dead runner&#39;s holds preempt automatically, and the session plane&#39;s own lock TTLs/<code>close_all</code> already run on every shutdown.</p><h2 id="what-ephemeral-does-not-change" tabindex="-1">What ephemeral does not change <a class="header-anchor" href="#what-ephemeral-does-not-change" aria-label="Permalink to &quot;What ephemeral does not change&quot;">​</a></h2><p>Auth, the <code>/api/*</code> surface, node identity persistence (<code>PEREGRIN_NODE</code>/<code>PEREGRIN_HOME</code> behave normally), and non-ephemeral shutdown behavior are all identical — the flag only adds the SIGTERM-aware shutdown and the snapshot flush. <code>peregrin serve</code> without the flag is byte-for-byte the old behavior.</p>`,20)])])}const E=e(t,[["render",h]]);export{c as __pageData,E as default};
